import React from 'react';
import { Link } from 'react-router-dom';
import { 
  LayoutDashboard, Users, ShoppingBag, CreditCard, 
  BarChart3, MessageSquare, Settings, LogOut, User, Shield,
  TrendingUp, Bell, FileText, Calendar, ShieldCheck,
  Database, Server, X
} from 'lucide-react';
import Badge from './';

const Sidebar = ({ sidebarOpen, currentPath, onLogout, isMobile }) => {
  // currentPath est maintenant passé en prop
  const userEmail = localStorage.getItem('userEmail') || 'enzo@gmail.com';

  const navItems = [
    { to: "/dashboard", icon: LayoutDashboard, label: "Tableau de bord", exact: true },
    { to: "/dashboard/users", icon: Users, label: "Utilisateurs", badge: "42", badgeColor: "accent" },
    { to: "/dashboard/products", icon: ShoppingBag, label: "Produits", badge: "156", badgeColor: "secondary" },
    { to: "/dashboard/orders", icon: CreditCard, label: "Commandes", badge: "24", badgeColor: "primary" },
    { to: "/dashboard/analytics", icon: BarChart3, label: "Analytique" },
    { to: "/dashboard/messages", icon: MessageSquare, label: "Messages", badge: "3", badgeColor: "accent" },
    { to: "/dashboard/settings", icon: Settings, label: "Paramètres" },
  ];

  const secondaryNav = [
    { to: "/dashboard/reports", icon: FileText, label: "Rapports" },
    { to: "/dashboard/calendar", icon: Calendar, label: "Calendrier" },
    { to: "/dashboard/notifications", icon: Bell, label: "Notifications" },
  ];

  const systemNav = [
    { to: "/dashboard/system", icon: Server, label: "Système" },
    { to: "/dashboard/database", icon: Database, label: "Base de données" },
    { to: "/dashboard/backup", icon: ShieldCheck, label: "Sauvegarde" },
  ];

  return (
    <>
      {/* Overlay pour mobile */}
      {isMobile && sidebarOpen && (
        <div 
          className="fixed inset-0 bg-black/50 z-40 lg:hidden"
          onClick={onLogout}
        />
      )}

      <aside className={`fixed inset-y-0 left-0 z-50 w-full md:w-64 bg-white/95 dark:bg-neutral-900/95 backdrop-blur-xl border-r border-neutral-200/50 dark:border-neutral-800/50 transform transition-transform duration-300 ${
        sidebarOpen ? 'translate-x-0' : '-translate-x-full'
      } md:translate-x-0`}>

        {/* En-tête mobile */}
        <div className="md:hidden p-4 border-b border-neutral-200/50 dark:border-neutral-800/50 flex items-center justify-between">
          <div className="flex items-center space-x-3">
            <div className="h-10 w-10 rounded-xl bg-gradient-to-r from-primary-500 to-secondary-500 flex items-center justify-center">
              <Shield className="h-6 w-6 text-white" />
            </div>
            <div>
              <h1 className="text-xl font-bold text-neutral-900 dark:text-white">AdminPro</h1>
              <p className="text-xs text-neutral-500 dark:text-neutral-400">Mobile</p>
            </div>
          </div>
          <button 
            onClick={onLogout}
            className="p-2 rounded-lg text-neutral-700 dark:text-neutral-300 hover:bg-neutral-100 dark:hover:bg-neutral-800"
          >
            <X className="h-5 w-5" />
          </button>
        </div>

        <div className="flex flex-col h-full">
          {/* Logo desktop */}
          <div className="hidden md:block p-6 border-b border-neutral-200/50 dark:border-neutral-800/50">
            <div className="flex items-center space-x-3">
              <div className="h-10 w-10 rounded-xl bg-gradient-to-r from-primary-500 to-secondary-500 flex items-center justify-center">
                <Shield className="h-6 w-6 text-white" />
              </div>
              <div>
                <h1 className="text-xl font-bold text-neutral-900 dark:text-white">Admin<span className="text-primary-600 dark:text-primary-400">Pro</span></h1>
                <p className="text-xs text-neutral-500 dark:text-neutral-400">Dashboard</p>
              </div>
            </div>
          </div>

          {/* User Profile */}
          <div className="p-4 md:p-6 border-b border-neutral-200/50 dark:border-neutral-800/50">
            <div className="flex items-center space-x-3">
              <div className="h-10 w-10 md:h-12 md:w-12 rounded-xl bg-gradient-to-r from-primary-500 to-accent-500 flex items-center justify-center">
                <User className="h-5 w-5 md:h-6 md:w-6 text-white" />
              </div>
              <div className="flex-1 min-w-0">
                <p className="text-sm md:text-base font-medium text-neutral-900 dark:text-white truncate">
                  Enzo Admin
                </p>
                <p className="text-xs text-neutral-500 dark:text-neutral-400 truncate">
                  {userEmail}
                </p>
                <div className="flex items-center mt-1">
                  <div className="h-2 w-2 rounded-full bg-green-500 mr-2"></div>
                  <span className="text-xs text-green-600 dark:text-green-400">En ligne</span>
                </div>
              </div>
            </div>
          </div>

          {/* Navigation principale */}
          <nav className="flex-1 p-4 overflow-y-auto">
            <div className="mb-6">
              <h3 className="hidden md:block text-xs font-semibold text-neutral-500 dark:text-neutral-400 uppercase tracking-wider mb-3 px-3">
                Navigation
              </h3>
              <ul className="space-y-1">
                {navItems.map((item) => {
                  const isActive = item.exact 
                    ? currentPath === item.to
                    : currentPath.startsWith(item.to);
                  const Icon = item.icon;

                  return (
                    <li key={item.to}>
                      <Link 
                        to={item.to} 
                        className={`flex items-center space-x-3 px-4 py-3 rounded-xl ${
                          isActive 
                            ? 'bg-gradient-to-r from-primary-500 to-primary-600 text-white font-medium shadow-lg shadow-primary-500/20' 
                            : 'text-neutral-700 dark:text-neutral-300 hover:bg-neutral-100 dark:hover:bg-neutral-800/50'
                        } transition-colors`}
                      >
                        <Icon className="h-5 w-5" />
                        <span className="flex-1">{item.label}</span>
                        {item.badge && (
                          <Badge 
                            color={item.badgeColor} 
                            size="sm"
                            className={isActive ? 'bg-white/20 hover:bg-white/30' : ''}
                          >
                            {item.badge}
                          </Badge>
                        )}
                      </Link>
                    </li>
                  );
                })}
              </ul>
            </div>

            {/* Stats - Desktop seulement */}
            <div className="hidden md:block mb-6 p-4 rounded-xl bg-gradient-to-r from-neutral-50 to-white dark:from-neutral-800 dark:to-neutral-900 border border-neutral-200/50 dark:border-neutral-700/50">
              <h3 className="text-sm font-medium text-neutral-700 dark:text-neutral-300 mb-4 flex items-center">
                <TrendingUp className="h-4 w-4 mr-2" />
                Statistiques
              </h3>
              <div className="space-y-3">
                <div className="flex items-center justify-between">
                  <span className="text-xs text-neutral-500 dark:text-neutral-400">Utilisateurs actifs</span>
                  <span className="text-sm font-medium text-neutral-900 dark:text-white">1,234</span>
                </div>
                <div className="flex items-center justify-between">
                  <span className="text-xs text-neutral-500 dark:text-neutral-400">Taux de conversion</span>
                  <span className="text-sm font-medium text-accent-500">3.42%</span>
                </div>
              </div>
            </div>

            {/* Navigation secondaire */}
            <div className="mb-6">
              <h3 className="hidden md:block text-xs font-semibold text-neutral-500 dark:text-neutral-400 uppercase tracking-wider mb-3 px-3">
                Outils
              </h3>
              <ul className="space-y-1">
                {secondaryNav.map((item) => {
                  const Icon = item.icon;
                  return (
                    <li key={item.to}>
                      <Link 
                        to={item.to} 
                        className="flex items-center space-x-3 px-4 py-2.5 rounded-xl text-neutral-600 dark:text-neutral-400 hover:bg-neutral-100 dark:hover:bg-neutral-800/50 transition-colors"
                      >
                        <Icon className="h-4 w-4" />
                        <span className="text-sm">{item.label}</span>
                      </Link>
                    </li>
                  );
                })}
              </ul>
            </div>
          </nav>

          {/* Footer */}
          <div className="p-4 border-t border-neutral-200/50 dark:border-neutral-800/50">
            <button
              onClick={onLogout}
              className="flex items-center justify-center space-x-2 w-full px-4 py-3 rounded-xl border border-red-200 dark:border-red-800 text-red-600 dark:text-red-400 hover:bg-red-50 dark:hover:bg-red-900/20 transition-colors mb-3"
            >
              <LogOut className="h-5 w-5" />
              <span className="font-medium">Déconnexion</span>
            </button>

            <div className="hidden md:flex items-center justify-between text-xs text-neutral-500 dark:text-neutral-500">
              <span>v2.1.0</span>
              <span>© 2024 AdminPro</span>
            </div>
          </div>
        </div>
      </aside>
    </>
  );
};

export default Sidebar;
